<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();verify_csrf();$to=(int)($_POST['reported_id']??0);$reason=$_POST['reason']??'';$allowed=['Inappropriate behavior','Spam','Fake profile','Harassment','Other'];if($to===(int)$u['id']||!in_array($reason,$allowed,true)){flash('danger','Please choose a valid report reason.');go('../student/find-partners.php');}db()->prepare('INSERT INTO reports(reporter_id,reported_id,reason,description) VALUES(?,?,?,?)')->execute([(int)$u['id'],$to,$reason,substr(trim($_POST['description']??''),0,4000)]);notify($to,'A community report was submitted for review.');flash('success','Thanks. Your report has been sent to the administrators.');go('../student/partner-details.php?id='.$to);
